def check_login(username, password, stored_users):
    # Check if username exists in stored users
    if username not in stored_users:
        return False, "Username not found"

    # Check if password matches
    if stored_users[username]["password"] != password:
        return False, "Incorrect password"

    # Check if the user is active (not banned)
    if not stored_users[username]["active"]:
        return False, "Account is banned"

    # Check if email is verified
    if not stored_users[username]["email_verified"]:
        return False, "Email not verified"

    # Login successful
    return True, "Login successful"

# Example usage:
stored_users = {
    "john_doe": {
        "password": "securepass123",
        "active": True,
        "email_verified": True
    },
    "jane_smith": {
        "password": "mypassword",
        "active": False,
        "email_verified": True
    },
    "bob_jones": {
        "password": "bobpass",
        "active": True,
        "email_verified": False
    }
}

# Test cases
print(check_login("john_doe", "securepass123", stored_users))  # Expected: (True, "Login successful")
print(check_login("john_doe", "wrongpass", stored_users))     # Expected: (False, "Incorrect password")
print(check_login("nonexistent", "pass", stored_users))       # Expected: (False, "Username not found")
print(check_login("jane_smith", "mypassword", stored_users))   # Expected: (False, "Account is banned")
print(check_login("bob_jones", "bobpass", stored_users))      # Expected: (False, "Email not verified")
